<?php
namespace App\Http\Controllers;
use App\Models\Appointment; use App\Models\Schedule; use App\Models\Service; use App\Models\ServiceAddon; use Illuminate\Http\Request; use Illuminate\Support\Carbon; use Illuminate\Support\Facades\DB;
class AppointmentController extends Controller {
 public function slots(Request $request) { $data=$request->validate(['barber_id'=>'required|integer','date'=>'required|date','total_duration_minutes'=>'required|integer|min:15']); $duration=(int)$data['total_duration_minutes']; $date=Carbon::parse($data['date']); $schedule=Schedule::where('barber_id',$data['barber_id'])->where('day_of_week',$date->dayOfWeek)->first(); if(!$schedule)return response()->json(['slots'=>[]]); $busy=Appointment::where('barber_id',$data['barber_id'])->whereDate('appointment_date',$date)->whereIn('status',['pending','confirmed'])->get(); $cursor=Carbon::parse($date->toDateString().' '.$schedule->start_time); $end=Carbon::parse($date->toDateString().' '.$schedule->end_time); $slots=[]; while($cursor->copy()->addMinutes($duration)->lte($end)){ $slotEnd=$cursor->copy()->addMinutes($duration); $breakStart=$schedule->break_start?Carbon::parse($date->toDateString().' '.$schedule->break_start):null; $breakEnd=$schedule->break_end?Carbon::parse($date->toDateString().' '.$schedule->break_end):null; $inBreak=$breakStart&&$cursor->lt($breakEnd)&&$slotEnd->gt($breakStart); $overlap=$busy->first(function($appointment)use($cursor,$slotEnd,$date){$busyStart=Carbon::parse($date->toDateString().' '.$appointment->start_time);$busyEnd=Carbon::parse($date->toDateString().' '.$appointment->end_time);return $cursor->lt($busyEnd)&&$slotEnd->gt($busyStart);}); if(!$inBreak&&!$overlap)$slots[]=$cursor->format('H:i'); $cursor->addMinutes(15); } return response()->json(['slots'=>$slots]); }
 public function store(Request $request) { $data=$request->validate(['barber_id'=>'required|exists:users,id','appointment_date'=>'required|date','start_time'=>'required|date_format:H:i','service_ids'=>'required|array|min:1','service_ids.*'=>'exists:services,id','addon_ids'=>'array','addon_ids.*'=>'exists:service_addons,id']); $services=Service::whereIn('id',$data['service_ids'])->get(); $addons=ServiceAddon::whereIn('id',$data['addon_ids']??[])->get(); $duration=$services->sum('duration_minutes')+$addons->sum('duration_minutes'); $start=Carbon::parse($data['appointment_date'].' '.$data['start_time']); $appointment=DB::transaction(function()use($data,$services,$addons,$start,$duration,$request){$appointment=Appointment::create(['client_id'=>$request->user()->id,'barber_id'=>$data['barber_id'],'appointment_date'=>$data['appointment_date'],'start_time'=>$start->format('H:i:s'),'end_time'=>$start->copy()->addMinutes($duration)->format('H:i:s'),'total_price'=>$services->sum('price')+$addons->sum('price'),'status'=>'confirmed']); foreach($services as $service)$appointment->services()->create(['service_id'=>$service->id]); foreach($addons as $addon)$appointment->services()->create(['service_id'=>$addon->service_id,'addon_id'=>$addon->id]); return $appointment; }); return response()->json($appointment->load('services'),201); }
}
